function retention_time(int $offset=0):string{return gmdate('Y-m-d H:i:s.000000',time()+$offset);}
function retention_audit(PDO $db,string $now,string $action,string $entityId,array $details):void
{
    $q=$db->prepare('INSERT INTO audit_events(occurred_at,actor_id,action,entity_type,entity_id,details_json) VALUES(?,?,?,?,?,?)');
    $q->execute([$now,'cleanup',$action,'mobile_intake_report',$entityId,json_encode($details,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES)]);
}
