    foreach($db->query('SELECT stored_path FROM mobile_intake_attachments WHERE deleted_at IS NULL')->fetchAll(PDO::FETCH_COLUMN) as $stored){$path=(string)$stored;$referenced[$path]=true;if(!str_starts_with($path,$root)){$outside++;continue;}if(!is_file($path))$missing++;}
    $orphans=0;$orphanBytes=0;foreach(glob($root.'*.bin')?:[] as $path)if(is_file($path)&&!isset($referenced[$path])){$orphans++;$size=filesize($path);if(is_int($size))$orphanBytes+=$size;}$staging=count(glob($root.'.upload-*.tmp')?:[]);
    $result=['retained_files'=>(int)$row['retained_files'],'retained_bytes'=>(int)$row['retained_bytes'],'oldest_retained'=>$row['oldest_retained'],'pending_cleanup'=>(int)$row['pending_cleanup'],'oldest_cleanup'=>$row['oldest_cleanup'],'pending_bytes'=>(int)$row['pending_bytes'],'expired_unrequested'=>(int)$row['expired_unrequested'],'missing_files'=>$missing,'outside_private_dir'=>$outside,'orphan_files'=>$orphans,'orphan_bytes'=>$orphanBytes,'staging_files'=>$staging];$result['clear']=$result['retained_files']===0&&$missing===0&&$outside===0&&$orphans===0&&$staging===0;return $result;
}

$configPath=$argv[1]??'';if($configPath===''||!is_file($configPath))throw new RuntimeException('independent retention config path is required');$cfg=require $configPath;
foreach(['db_dsn','db_user','db_password','private_dir'] as $key)if(!array_key_exists($key,$cfg)||!is_string($cfg[$key]))throw new RuntimeException('retention config is incomplete');
$privateDir=rtrim($cfg['private_dir'],'/');if($privateDir===''||$privateDir[0]!=='/'||str_contains($privateDir,'/public_html')||!is_dir($privateDir)||!is_writable($privateDir))throw new RuntimeException('retention private directory is invalid');
$db=new PDO($cfg['db_dsn'],$cfg['db_user'],$cfg['db_password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$now=retention_time();$abandoned=retention_time(-86400);$retention=retention_time(-2592000);$root=$privateDir.'/';
$expiredResult=json_encode(['actual_revisions'=>[],'authoritative_record_ids'=>[],'evidence_durable'=>false,'reason'=>'attachment_upload_expired'],JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES);$db->prepare("UPDATE mobile_intake_reports SET status='rejected',result_json=?,resolved_at=?,revision=revision+1,updated_at=? WHERE status='pending_review' AND attachment_count>(SELECT COUNT(*) FROM mobile_intake_attachments a WHERE a.report_uuid=mobile_intake_reports.report_uuid AND a.deleted_at IS NULL AND a.upload_state='complete') AND received_at<?")->execute([$expiredResult,$now,$now,$abandoned]);
$q=$db->prepare('SELECT DISTINCT report_uuid FROM mobile_intake_attachments WHERE deleted_at IS NULL AND uploaded_at<?');$q->execute([$retention]);foreach($q->fetchAll(PDO::FETCH_COLUMN) as $reportUuid){$db->prepare('UPDATE mobile_intake_attachments SET delete_requested_at=COALESCE(delete_requested_at,?),cleanup_next_at=COALESCE(cleanup_next_at,?) WHERE report_uuid=? AND deleted_at IS NULL')->execute([$now,$now,(string)$reportUuid]);$result=json_encode(['actual_revisions'=>[],'authoritative_record_ids'=>[],'evidence_durable'=>false,'reason'=>'attachment_retention_expired'],JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES);$db->prepare("UPDATE mobile_intake_reports SET status='rejected',result_json=?,resolved_at=?,lease_token_hash=NULL,lease_until=NULL,revision=revision+1,updated_at=? WHERE report_uuid=? AND status IN ('pending_review','leased')")->execute([$result,$now,$now,(string)$reportUuid]);}
$cleanup=$db->prepare('SELECT attachment_uuid,report_uuid,stored_path,cleanup_attempts FROM mobile_intake_attachments WHERE deleted_at IS NULL AND delete_requested_at IS NOT NULL AND (cleanup_next_at IS NULL OR cleanup_next_at<=?) ORDER BY delete_requested_at LIMIT 500');$cleanup->execute([$now]);$deleted=0;
foreach($cleanup->fetchAll(PDO::FETCH_ASSOC) as $row){$path=(string)$row['stored_path'];$inside=str_starts_with($path,$root);if($inside&&(!is_file($path)||@unlink($path))){$db->prepare('UPDATE mobile_intake_attachments SET deleted_at=?,cleanup_last_error=NULL WHERE attachment_uuid=? AND deleted_at IS NULL')->execute([$now,(string)$row['attachment_uuid']]);retention_audit($db,$now,'mobile.intake.attachment_deleted',(string)$row['report_uuid'],['attachment_uuid'=>(string)$row['attachment_uuid'],'maintenance_version'=>'v1']);$deleted++;continue;}$attempt=(int)$row['cleanup_attempts']+1;$delay=min(86400,60*(2**min(10,$attempt)));$next=retention_time($delay);$error=$inside?'unlink_failed':'path_outside_private_dir';$db->prepare('UPDATE mobile_intake_attachments SET cleanup_attempts=?,cleanup_next_at=?,cleanup_last_error=? WHERE attachment_uuid=?')->execute([$attempt,$next,$error,(string)$row['attachment_uuid']]);retention_audit($db,$now,'mobile.intake.attachment_cleanup_failed',(string)$row['report_uuid'],['attachment_uuid'=>(string)$row['attachment_uuid'],'attempt'=>$attempt,'retry_at'=>$next,'reason'=>$error,'maintenance_version'=>'v1']);}
$orphanDeleted=0;foreach(glob($root.'*.bin')?:[] as $path){$known=$db->prepare('SELECT COUNT(*) FROM mobile_intake_attachments WHERE stored_path=? AND deleted_at IS NULL');$known->execute([$path]);if((int)$known->fetchColumn()!==0||filemtime($path)>=time()-2592000)continue;if(@unlink($path)){$orphanDeleted++;retention_audit($db,$now,'mobile.intake.orphan_deleted',basename($path),['maintenance_version'=>'v1']);}}
$stagingDeleted=0;foreach(glob($root.'.upload-*.tmp')?:[] as $path)if(is_file($path)&&filemtime($path)<time()-86400&&@unlink($path)){$stagingDeleted++;retention_audit($db,$now,'mobile.intake.staging_deleted',basename($path),['maintenance_version'=>'v1']);}
